/* sysfont.h - XGDOS's built-in system bitmap fonts (the EmuTOS 6x6, 8x8
 * and 8x16 fonts in the Atari ST character set), used on its own devices
 * instead of the ROM fonts, so nothing depends on the deprecated Line-A
 * interface. Data in sysfont.c (generated by tools/mksysfont.py). */
#ifndef SYSFONT_H
#define SYSFONT_H
#include "xtypes.h"

typedef struct SysFont {
    s16 w, h;            /* cell size; one byte per glyph row, MSB = left */
    s16 top;             /* rows above the baseline: the baseline is row top */
    s16 asc, half;       /* ascent and half line, from the baseline */
    s16 desc, bot;       /* descent and bottom, below the baseline */
    const u8 *bits;      /* 256 glyphs * h rows */
} SysFont;

extern const SysFont xg_sysfonts[3];    /* 6x6 (8 pt), 8x8 (9 pt), 8x16 (10 pt) */

#endif
